function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // bookshelf
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(50, 50, W - 100, H - 100);
  ctx.stroke();

  // books
  for (let i = 0; i < 10; i++) {
    ctx.fillStyle = 'black';
    ctx.fillRect(60 + i * 30, 60 + Math.sin(t + i) * 20, 20, 50);
  }

  // stick figure reading
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 20);
  ctx.lineTo(W / 2, H / 2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 30);
  ctx.lineTo(W / 2 - 20, H / 2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 30);
  ctx.lineTo(W / 2 + 20, H / 2 + 40);
  ctx.stroke();

  // energy lines
  ctx.lineWidth = 2;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(W / 2, H / 2 + 50);
    ctx.lineTo(W / 2 + Math.cos(t + i) * 50, H / 2 + 100 + Math.sin(t + i) * 20);
    ctx.stroke();
  }

  ctx.restore();
}
